typedef int bool32;

class stringx
{
    char *data;
    char *buffer;

public:
    stringx(const char *);
    ~stringx();
    stringx &operator=(const char *);
    stringx &operator+=(const char *);
    const char *c_str() const;
};

class ps2_joypad_device
{
public:
    int device_id;

    ps2_joypad_device(int which_port = 0, int which_slot = 0);
    virtual ~ps2_joypad_device();
    virtual void get_name() const;
    virtual void get_axis_name(int) const;
    virtual int get_id() const;
    virtual int get_axis_count() const;
    virtual int get_axis_id(int) const;
    virtual float get_axis_state(int, int) const;
    virtual float get_axis_old_state(int, int) const;
    virtual float get_axis_delta(int, int) const;
    virtual bool is_connected() const;

private:
    char state[91];
    bool port_opened;

public:
    bool is_port_open() const { return port_opened; }
};

class ps2_input_mgr
{
public:
    ps2_input_mgr();

private:
    ps2_joypad_device *pad[2];
    int max_keyb;
};

extern const char *nglHostPrefix;
extern ps2_joypad_device *g_pad;
extern "C" void nglPrintf(const char *, ...);
extern "C" int sceSifInitRpc(int);
extern "C" int sceCdSync(int);
extern "C" int scePadInit(int);
extern bool load_iop_module(const char *, const char *);

#define false 0
#define NULL 0
#define assert(condition) ((void)0)
#define PS2_MAX_PORTS 2
#define PS2_MAX_SLOTS 1
#define PORT_SLOT_TO_CONTROL_NUM(port, slot) (((port) * PS2_MAX_SLOTS) + (slot))
#define JOYSTICK_TO_DEVICE_ID(id) (((id) - 1) + 3)
#define INVALID_DEVICE_ID -1

ps2_input_mgr::ps2_input_mgr()
{
	nglPrintf("ps2 input init\n");

	sceSifInitRpc(0);

	sceCdSync(0);

	stringx debug_dir(nglHostPrefix);
	debug_dir += "c:\\usr\\local\\sce\\iop\\modules\\";


	// $jim - I moved this to ps2_storage.cpp as I need it earlier than here for memcard init.

	if (load_iop_module("sio2man.irx", debug_dir.c_str()) == false)
	{
		nglPrintf("Can't load module sio2man\n");
		assert(0);
	}


	debug_dir = nglHostPrefix;
	debug_dir += "c:\\usr\\local\\sce\\iop\\modules\\";
	if (load_iop_module("padman.irx", debug_dir.c_str()) == false)
	{
		nglPrintf("Can't load module padman\n");
		assert(0);
	}

	// --- pad open ---
	scePadInit(0);

	g_pad = NULL;
	int joystick_num = 1;
	for(int _port=0; _port < PS2_MAX_PORTS; ++_port)
	{
		for(int _slot=0; _slot < PS2_MAX_SLOTS; ++_slot)
		{
			int control_num = PORT_SLOT_TO_CONTROL_NUM(_port, _slot);
			pad[control_num] = new ps2_joypad_device(_port, _slot);
			if(pad[control_num]->is_port_open() && pad[control_num]->is_connected())
			{
				pad[control_num]->device_id = JOYSTICK_TO_DEVICE_ID(joystick_num);
				++joystick_num; 
				if(g_pad == NULL)
					g_pad = pad[control_num];
			}
			else
				pad[control_num]->device_id = INVALID_DEVICE_ID;
		}
	}
	if(g_pad == NULL)
		g_pad = pad[0];
}
